CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Employee sign-in identity. Interviewers, recruiters and approvers are all rows here.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name shown on scorecards and interview invitations.
	"full_name" VARCHAR(160) NOT NULL,
	-- Their own role, shown to candidates on the schedule so they know who they are meeting.
	"job_title" VARCHAR(160),
	-- Used to route approvals and to find interviewers with the right context.
	"department" VARCHAR(120),
	-- IANA zone. Scheduling across timezones is most of the operational pain in recruiting, so it is stored, never inferred.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Leavers keep authorship of their scorecards; deactivation only removes them from scheduling.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'An employee involved in hiring. Deliberately not the same table as candidates, even though people are hired and become employees — the two have different lifecycles, different retention rules and very different access rights.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Employee sign-in identity. Interviewers, recruiters and approvers are all rows here.';
COMMENT ON COLUMN "users"."full_name" IS 'Name shown on scorecards and interview invitations.';
COMMENT ON COLUMN "users"."job_title" IS 'Their own role, shown to candidates on the schedule so they know who they are meeting.';
COMMENT ON COLUMN "users"."department" IS 'Used to route approvals and to find interviewers with the right context.';
COMMENT ON COLUMN "users"."timezone" IS 'IANA zone. Scheduling across timezones is most of the operational pain in recruiting, so it is stored, never inferred.';
COMMENT ON COLUMN "users"."is_active" IS 'Leavers keep authorship of their scorecards; deactivation only removes them from scheduling.';

CREATE TABLE IF NOT EXISTS "jobs" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Public job title as advertised.
	"title" VARCHAR(200) NOT NULL,
	-- Owning department, the unit headcount is budgeted against.
	"department" VARCHAR(120) NOT NULL,
	-- Primary location, or null for fully remote roles.
	"location" VARCHAR(160),
	-- full_time | part_time | contract | intern. Changes the offer shape and the approval chain.
	"employment_type" VARCHAR(24) NOT NULL DEFAULT 'full_time',
	-- draft | open | on_hold | closed | filled. on_hold is distinct from closed because candidates in flight still need a pipeline to sit in.
	"status" VARCHAR(20) NOT NULL DEFAULT 'draft',
	-- Headcount approved. Compared against accepted offers to decide when the job is filled — a role with three openings stays open after the first hire.
	"openings_count" SMALLINT NOT NULL DEFAULT 1,
	-- Accepted offers so far. Denormalised because every recruiter dashboard needs it.
	"filled_count" SMALLINT NOT NULL DEFAULT 0,
	-- Owning recruiter, responsible for the pipeline.
	"recruiter_user_id" BIGINT,
	-- Manager the role reports to, and the decision maker on the hire.
	"hiring_manager_user_id" BIGINT,
	-- Bottom of the approved band in minor units. Stored because offers outside the band need extra approval.
	"salary_min_minor" BIGINT,
	-- Top of the approved band.
	"salary_max_minor" BIGINT,
	-- ISO 4217 for the band.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- When the role went live, the start of time-to-fill.
	"opened_at" TIMESTAMP,
	-- When it stopped accepting applications.
	"closed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "jobs" IS 'The requisition. Openings are a count rather than individual rows, which keeps the common case simple; a role whose openings need separate budget codes or start dates is the point at which they earn their own table.';
COMMENT ON COLUMN "jobs"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "jobs"."title" IS 'Public job title as advertised.';
COMMENT ON COLUMN "jobs"."department" IS 'Owning department, the unit headcount is budgeted against.';
COMMENT ON COLUMN "jobs"."location" IS 'Primary location, or null for fully remote roles.';
COMMENT ON COLUMN "jobs"."employment_type" IS 'full_time | part_time | contract | intern. Changes the offer shape and the approval chain.';
COMMENT ON COLUMN "jobs"."status" IS 'draft | open | on_hold | closed | filled. on_hold is distinct from closed because candidates in flight still need a pipeline to sit in.';
COMMENT ON COLUMN "jobs"."openings_count" IS 'Headcount approved. Compared against accepted offers to decide when the job is filled — a role with three openings stays open after the first hire.';
COMMENT ON COLUMN "jobs"."filled_count" IS 'Accepted offers so far. Denormalised because every recruiter dashboard needs it.';
COMMENT ON COLUMN "jobs"."recruiter_user_id" IS 'Owning recruiter, responsible for the pipeline.';
COMMENT ON COLUMN "jobs"."hiring_manager_user_id" IS 'Manager the role reports to, and the decision maker on the hire.';
COMMENT ON COLUMN "jobs"."salary_min_minor" IS 'Bottom of the approved band in minor units. Stored because offers outside the band need extra approval.';
COMMENT ON COLUMN "jobs"."salary_max_minor" IS 'Top of the approved band.';
COMMENT ON COLUMN "jobs"."currency_code" IS 'ISO 4217 for the band.';
COMMENT ON COLUMN "jobs"."opened_at" IS 'When the role went live, the start of time-to-fill.';
COMMENT ON COLUMN "jobs"."closed_at" IS 'When it stopped accepting applications.';

CREATE INDEX "idx_jobs_status_department"
ON "jobs" ("status", "department");

CREATE TABLE IF NOT EXISTS "hiring_team_members" (
	-- Job being staffed. Part of the composite key.
	"job_id" BIGINT,
	-- Employee on the team. Part of the composite key.
	"user_id" BIGINT,
	-- recruiter | hiring_manager | interviewer | coordinator | approver. Drives both scheduling suggestions and who can see candidate data.
	"team_role" VARCHAR(24) NOT NULL DEFAULT 'interviewer',
	-- False for interviewers who must not see others feedback before submitting their own.
	"can_view_scorecards" BOOLEAN NOT NULL DEFAULT true,
	-- When they joined the team.
	"added_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("job_id", "user_id")
);

COMMENT ON TABLE "hiring_team_members" IS 'Who works on a job, and in what capacity. Access to candidate records is derived from this table rather than from a global role, because most companies want interviewers to see only the candidates they are actually meeting.';
COMMENT ON COLUMN "hiring_team_members"."job_id" IS 'Job being staffed. Part of the composite key.';
COMMENT ON COLUMN "hiring_team_members"."user_id" IS 'Employee on the team. Part of the composite key.';
COMMENT ON COLUMN "hiring_team_members"."team_role" IS 'recruiter | hiring_manager | interviewer | coordinator | approver. Drives both scheduling suggestions and who can see candidate data.';
COMMENT ON COLUMN "hiring_team_members"."can_view_scorecards" IS 'False for interviewers who must not see others feedback before submitting their own.';
COMMENT ON COLUMN "hiring_team_members"."added_at" IS 'When they joined the team.';

CREATE TABLE IF NOT EXISTS "candidates" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The person identity, and the deduplication key that lets a repeat applicant be recognised across years and roles.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Given name.
	"first_name" VARCHAR(120) NOT NULL,
	-- Family name.
	"last_name" VARCHAR(120) NOT NULL,
	-- Free text; international formats defeat normalisation.
	"phone" VARCHAR(40),
	-- Where they are based, which decides visa and relocation conversations early.
	"location" VARCHAR(160),
	-- Profile link, usually the fastest sourcing context.
	"linkedin_url" VARCHAR(255),
	-- job_board | referral | sourced | agency | career_site | event. Recorded once on the person and again per application, because a referred candidate can later apply directly.
	"source" VARCHAR(40),
	-- Employee who referred them. Null for everyone else, and the basis of referral bonus reporting.
	"referred_by_user_id" BIGINT,
	-- When the retention period for this personal data ends. GDPR makes deletion a scheduled job, not a support request.
	"consent_expires_at" TIMESTAMP,
	-- First time this person entered the system.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "candidates" IS 'The person, independent of any job. Keeping candidates separate from applications is what lets someone apply to three roles over two years and still be one record with one history — and what makes a deletion request a single row to act on.';
COMMENT ON COLUMN "candidates"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "candidates"."email" IS 'The person identity, and the deduplication key that lets a repeat applicant be recognised across years and roles.';
COMMENT ON COLUMN "candidates"."first_name" IS 'Given name.';
COMMENT ON COLUMN "candidates"."last_name" IS 'Family name.';
COMMENT ON COLUMN "candidates"."phone" IS 'Free text; international formats defeat normalisation.';
COMMENT ON COLUMN "candidates"."location" IS 'Where they are based, which decides visa and relocation conversations early.';
COMMENT ON COLUMN "candidates"."linkedin_url" IS 'Profile link, usually the fastest sourcing context.';
COMMENT ON COLUMN "candidates"."source" IS 'job_board | referral | sourced | agency | career_site | event. Recorded once on the person and again per application, because a referred candidate can later apply directly.';
COMMENT ON COLUMN "candidates"."referred_by_user_id" IS 'Employee who referred them. Null for everyone else, and the basis of referral bonus reporting.';
COMMENT ON COLUMN "candidates"."consent_expires_at" IS 'When the retention period for this personal data ends. GDPR makes deletion a scheduled job, not a support request.';
COMMENT ON COLUMN "candidates"."created_at" IS 'First time this person entered the system.';

CREATE TABLE IF NOT EXISTS "job_stages" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Job this stage belongs to. Stages are per job because a designer pipeline and an engineer pipeline genuinely differ.
	"job_id" BIGINT NOT NULL,
	-- Stage name, e.g. "Technical screen".
	"name" VARCHAR(120) NOT NULL,
	-- Order in the pipeline. Gaps allowed so a stage can be inserted without renumbering.
	"position" SMALLINT NOT NULL,
	-- applied | screen | interview | assessment | offer | hired. Reporting groups on the type, so renaming a stage does not break the funnel chart.
	"stage_type" VARCHAR(24) NOT NULL DEFAULT 'interview',
	-- Attributes interviewers must rate at this stage, which is what makes the feedback comparable between candidates.
	"scorecard_attributes" JSONB,
	-- True for hired and for any stage from which no further movement happens.
	"is_terminal" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "job_stages" IS 'The per-job pipeline. Copied from a template when the job is created rather than referenced, so editing the company default next quarter cannot reshuffle candidates already mid-process.';
COMMENT ON COLUMN "job_stages"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "job_stages"."job_id" IS 'Job this stage belongs to. Stages are per job because a designer pipeline and an engineer pipeline genuinely differ.';
COMMENT ON COLUMN "job_stages"."name" IS 'Stage name, e.g. "Technical screen".';
COMMENT ON COLUMN "job_stages"."position" IS 'Order in the pipeline. Gaps allowed so a stage can be inserted without renumbering.';
COMMENT ON COLUMN "job_stages"."stage_type" IS 'applied | screen | interview | assessment | offer | hired. Reporting groups on the type, so renaming a stage does not break the funnel chart.';
COMMENT ON COLUMN "job_stages"."scorecard_attributes" IS 'Attributes interviewers must rate at this stage, which is what makes the feedback comparable between candidates.';
COMMENT ON COLUMN "job_stages"."is_terminal" IS 'True for hired and for any stage from which no further movement happens.';

CREATE UNIQUE INDEX "uq_job_stages_position"
ON "job_stages" ("job_id", "position");

CREATE TABLE IF NOT EXISTS "applications" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Person applying.
	"candidate_id" BIGINT NOT NULL,
	-- Role applied for.
	"job_id" BIGINT NOT NULL,
	-- Where they are now. Null only between application and triage.
	"current_stage_id" BIGINT,
	-- active | hired | rejected | withdrawn | on_hold. Withdrawn is the candidate decision and rejected is yours; conflating them ruins funnel analysis.
	"status" VARCHAR(20) NOT NULL DEFAULT 'active',
	-- How this particular application arrived, which can differ from how the candidate was first found.
	"source" VARCHAR(40),
	-- skills_gap | experience_level | compensation | location | timing | position_closed | offer_declined. A string rather than a lookup table, but a fixed vocabulary — free text here produces a hundred spellings of "not a fit".
	"rejection_reason" VARCHAR(60),
	-- Stage they were rejected at, snapshotted so the drop-off curve stays correct when stages are later edited.
	"rejection_stage_id" BIGINT,
	-- Who made the call. Null for automated screening.
	"rejected_by_user_id" BIGINT,
	-- Application time, the start of time-to-hire for this application.
	"applied_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Most recent movement. The column that surfaces candidates going stale in a pipeline.
	"last_activity_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "applications" IS 'One candidate applying to one job — the row everything else hangs off. The unique key stops the same person entering the same pipeline twice, while leaving them free to apply to any number of other roles.';
COMMENT ON COLUMN "applications"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "applications"."candidate_id" IS 'Person applying.';
COMMENT ON COLUMN "applications"."job_id" IS 'Role applied for.';
COMMENT ON COLUMN "applications"."current_stage_id" IS 'Where they are now. Null only between application and triage.';
COMMENT ON COLUMN "applications"."status" IS 'active | hired | rejected | withdrawn | on_hold. Withdrawn is the candidate decision and rejected is yours; conflating them ruins funnel analysis.';
COMMENT ON COLUMN "applications"."source" IS 'How this particular application arrived, which can differ from how the candidate was first found.';
COMMENT ON COLUMN "applications"."rejection_reason" IS 'skills_gap | experience_level | compensation | location | timing | position_closed | offer_declined. A string rather than a lookup table, but a fixed vocabulary — free text here produces a hundred spellings of "not a fit".';
COMMENT ON COLUMN "applications"."rejection_stage_id" IS 'Stage they were rejected at, snapshotted so the drop-off curve stays correct when stages are later edited.';
COMMENT ON COLUMN "applications"."rejected_by_user_id" IS 'Who made the call. Null for automated screening.';
COMMENT ON COLUMN "applications"."applied_at" IS 'Application time, the start of time-to-hire for this application.';
COMMENT ON COLUMN "applications"."last_activity_at" IS 'Most recent movement. The column that surfaces candidates going stale in a pipeline.';

CREATE UNIQUE INDEX "uq_application_candidate_job"
ON "applications" ("candidate_id", "job_id");
CREATE INDEX "idx_applications_pipeline"
ON "applications" ("job_id", "status", "current_stage_id");
CREATE INDEX "idx_applications_stale"
ON "applications" ("status", "last_activity_at");

CREATE TABLE IF NOT EXISTS "interviews" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Application being assessed.
	"application_id" BIGINT NOT NULL,
	-- Stage this interview belongs to. Null for an ad-hoc conversation outside the defined pipeline.
	"stage_id" BIGINT,
	-- What the candidate sees in the invitation, e.g. "System design".
	"title" VARCHAR(160) NOT NULL,
	-- Start instant in UTC. Null while the interview is requested but not yet booked.
	"scheduled_start" TIMESTAMP,
	-- End instant in UTC.
	"scheduled_end" TIMESTAMP,
	-- IANA zone the slot was agreed in, kept beside the UTC instants so a rescheduled slot keeps its human meaning across a daylight-saving change.
	"timezone" VARCHAR(64),
	-- Room or address for onsite interviews.
	"location" VARCHAR(255),
	-- Video link for remote interviews.
	"meeting_url" VARCHAR(500),
	-- requested | scheduled | completed | canceled | no_show. no_show is tracked separately because it is a real and reportable outcome.
	"status" VARCHAR(20) NOT NULL DEFAULT 'requested',
	-- Coordinator or recruiter who arranged it.
	"created_by_user_id" BIGINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "interviews" IS 'A scheduled assessment. It belongs to the application rather than to the candidate, because the same person interviewing for two roles is two independent processes that must not leak into each other.';
COMMENT ON COLUMN "interviews"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "interviews"."application_id" IS 'Application being assessed.';
COMMENT ON COLUMN "interviews"."stage_id" IS 'Stage this interview belongs to. Null for an ad-hoc conversation outside the defined pipeline.';
COMMENT ON COLUMN "interviews"."title" IS 'What the candidate sees in the invitation, e.g. "System design".';
COMMENT ON COLUMN "interviews"."scheduled_start" IS 'Start instant in UTC. Null while the interview is requested but not yet booked.';
COMMENT ON COLUMN "interviews"."scheduled_end" IS 'End instant in UTC.';
COMMENT ON COLUMN "interviews"."timezone" IS 'IANA zone the slot was agreed in, kept beside the UTC instants so a rescheduled slot keeps its human meaning across a daylight-saving change.';
COMMENT ON COLUMN "interviews"."location" IS 'Room or address for onsite interviews.';
COMMENT ON COLUMN "interviews"."meeting_url" IS 'Video link for remote interviews.';
COMMENT ON COLUMN "interviews"."status" IS 'requested | scheduled | completed | canceled | no_show. no_show is tracked separately because it is a real and reportable outcome.';
COMMENT ON COLUMN "interviews"."created_by_user_id" IS 'Coordinator or recruiter who arranged it.';

CREATE INDEX "idx_interviews_application"
ON "interviews" ("application_id", "scheduled_start");
CREATE INDEX "idx_interviews_calendar"
ON "interviews" ("scheduled_start", "status");

CREATE TABLE IF NOT EXISTS "interview_panelists" (
	-- Interview being staffed. Part of the composite key.
	"interview_id" BIGINT,
	-- Employee on the panel. Part of the composite key.
	"user_id" BIGINT,
	-- lead | interviewer | shadow. Shadows are being trained and their scorecards are excluded from the decision.
	"panel_role" VARCHAR(20) NOT NULL DEFAULT 'interviewer',
	-- accepted | declined | tentative. Null until the calendar invite is answered — and the reason half of recruiting coordination exists.
	"invite_response" VARCHAR(16),
	-- Optional panelists do not block rescheduling.
	"is_required" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("interview_id", "user_id")
);

COMMENT ON TABLE "interview_panelists" IS 'The panel as rows, so a loop interview with four people is four rows and four scorecards. Putting a single interviewer column on the interview instead is what forces teams to create four near-duplicate interviews for one conversation.';
COMMENT ON COLUMN "interview_panelists"."interview_id" IS 'Interview being staffed. Part of the composite key.';
COMMENT ON COLUMN "interview_panelists"."user_id" IS 'Employee on the panel. Part of the composite key.';
COMMENT ON COLUMN "interview_panelists"."panel_role" IS 'lead | interviewer | shadow. Shadows are being trained and their scorecards are excluded from the decision.';
COMMENT ON COLUMN "interview_panelists"."invite_response" IS 'accepted | declined | tentative. Null until the calendar invite is answered — and the reason half of recruiting coordination exists.';
COMMENT ON COLUMN "interview_panelists"."is_required" IS 'Optional panelists do not block rescheduling.';

CREATE TABLE IF NOT EXISTS "scorecards" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Interview the feedback is for.
	"interview_id" BIGINT NOT NULL,
	-- Author. Feedback is attributed, because anonymous scorecards are not defensible in a discrimination claim.
	"interviewer_user_id" BIGINT NOT NULL,
	-- Denormalised from the interview so all feedback on a candidate reads without a join through interviews.
	"application_id" BIGINT NOT NULL,
	-- strong_yes | yes | no | strong_no. Deliberately four options with no middle, which forces a decision instead of a shrug.
	"overall_recommendation" VARCHAR(20),
	-- Evidence for the rating. The part a hiring manager actually reads.
	"notes" TEXT,
	-- Submission time. Null means outstanding, and an unsubmitted scorecard should block the debrief.
	"submitted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "scorecards" IS 'One scorecard per interviewer per interview. The unique key is what makes "who still owes feedback" a query rather than a chase, and submission time is kept so feedback written after seeing the panel discussion can be spotted.';
COMMENT ON COLUMN "scorecards"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "scorecards"."interview_id" IS 'Interview the feedback is for.';
COMMENT ON COLUMN "scorecards"."interviewer_user_id" IS 'Author. Feedback is attributed, because anonymous scorecards are not defensible in a discrimination claim.';
COMMENT ON COLUMN "scorecards"."application_id" IS 'Denormalised from the interview so all feedback on a candidate reads without a join through interviews.';
COMMENT ON COLUMN "scorecards"."overall_recommendation" IS 'strong_yes | yes | no | strong_no. Deliberately four options with no middle, which forces a decision instead of a shrug.';
COMMENT ON COLUMN "scorecards"."notes" IS 'Evidence for the rating. The part a hiring manager actually reads.';
COMMENT ON COLUMN "scorecards"."submitted_at" IS 'Submission time. Null means outstanding, and an unsubmitted scorecard should block the debrief.';

CREATE UNIQUE INDEX "uq_scorecard_interview_author"
ON "scorecards" ("interview_id", "interviewer_user_id");
CREATE INDEX "idx_scorecards_application"
ON "scorecards" ("application_id", "submitted_at");

CREATE TABLE IF NOT EXISTS "scorecard_ratings" (
	-- Parent scorecard. Part of the composite key.
	"scorecard_id" BIGINT,
	-- Attribute rated, drawn from the stage scorecard_attributes list. Part of the key, so one attribute cannot be scored twice.
	"attribute" VARCHAR(80),
	-- 1 to 4 against the defined rubric. An even scale on purpose: a five-point scale collects a pile of threes that mean nothing.
	"rating" SMALLINT NOT NULL,
	-- Evidence for this specific attribute, which is what makes two candidates comparable months apart.
	"comment" TEXT,
	PRIMARY KEY("scorecard_id", "attribute")
);

COMMENT ON TABLE "scorecard_ratings" IS 'Per-attribute structured ratings, the whole point of a scorecard. An overall thumbs-up is a feeling; a row per attribute against a shared rubric is the only thing that supports a defensible comparison between candidates interviewed by different people.';
COMMENT ON COLUMN "scorecard_ratings"."scorecard_id" IS 'Parent scorecard. Part of the composite key.';
COMMENT ON COLUMN "scorecard_ratings"."attribute" IS 'Attribute rated, drawn from the stage scorecard_attributes list. Part of the key, so one attribute cannot be scored twice.';
COMMENT ON COLUMN "scorecard_ratings"."rating" IS '1 to 4 against the defined rubric. An even scale on purpose: a five-point scale collects a pile of threes that mean nothing.';
COMMENT ON COLUMN "scorecard_ratings"."comment" IS 'Evidence for this specific attribute, which is what makes two candidates comparable months apart.';

CREATE TABLE IF NOT EXISTS "offers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Application being offered. One live offer per application, enforced by the application layer since superseded versions stay for the record.
	"application_id" BIGINT NOT NULL,
	-- draft | pending_approval | approved | sent | accepted | declined | rescinded | expired. Approval sits between draft and sent because a leaked unapproved number cannot be retracted.
	"status" VARCHAR(24) NOT NULL DEFAULT 'draft',
	-- Revision counter. A renegotiated offer is a new row, not an edit, so the approval chain applies to what was actually sent.
	"version" SMALLINT NOT NULL DEFAULT 1,
	-- Annual base in minor units. Integer, because salary bands and equity maths summed as floats drift.
	"base_salary_minor" BIGINT NOT NULL,
	-- ISO 4217 for every amount on the offer.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- One-off bonus. Null when none is offered.
	"signing_bonus_minor" BIGINT,
	-- Share or option count. Deliberately units, not a valuation, because the valuation changes and the grant does not.
	"equity_units" INTEGER,
	-- Agreed first day. A local calendar date, not a timestamp.
	"start_date" DATE,
	-- Decision deadline given to the candidate.
	"expires_at" TIMESTAMP,
	-- When it went out.
	"sent_at" TIMESTAMP,
	-- When the candidate accepted or declined.
	"responded_at" TIMESTAMP,
	-- compensation | counter_offer | other_offer | role_scope | location | personal. The single most valuable field for fixing a losing offer strategy.
	"declined_reason" VARCHAR(60),
	-- Recruiter who drafted it.
	"created_by_user_id" BIGINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "offers" IS 'The offer as a versioned document. Every amount is snapshotted rather than referenced from the job band, because an offer is a commitment that must read identically after the band is revised.';
COMMENT ON COLUMN "offers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "offers"."application_id" IS 'Application being offered. One live offer per application, enforced by the application layer since superseded versions stay for the record.';
COMMENT ON COLUMN "offers"."status" IS 'draft | pending_approval | approved | sent | accepted | declined | rescinded | expired. Approval sits between draft and sent because a leaked unapproved number cannot be retracted.';
COMMENT ON COLUMN "offers"."version" IS 'Revision counter. A renegotiated offer is a new row, not an edit, so the approval chain applies to what was actually sent.';
COMMENT ON COLUMN "offers"."base_salary_minor" IS 'Annual base in minor units. Integer, because salary bands and equity maths summed as floats drift.';
COMMENT ON COLUMN "offers"."currency_code" IS 'ISO 4217 for every amount on the offer.';
COMMENT ON COLUMN "offers"."signing_bonus_minor" IS 'One-off bonus. Null when none is offered.';
COMMENT ON COLUMN "offers"."equity_units" IS 'Share or option count. Deliberately units, not a valuation, because the valuation changes and the grant does not.';
COMMENT ON COLUMN "offers"."start_date" IS 'Agreed first day. A local calendar date, not a timestamp.';
COMMENT ON COLUMN "offers"."expires_at" IS 'Decision deadline given to the candidate.';
COMMENT ON COLUMN "offers"."sent_at" IS 'When it went out.';
COMMENT ON COLUMN "offers"."responded_at" IS 'When the candidate accepted or declined.';
COMMENT ON COLUMN "offers"."declined_reason" IS 'compensation | counter_offer | other_offer | role_scope | location | personal. The single most valuable field for fixing a losing offer strategy.';
COMMENT ON COLUMN "offers"."created_by_user_id" IS 'Recruiter who drafted it.';

CREATE UNIQUE INDEX "uq_offers_application_version"
ON "offers" ("application_id", "version");
CREATE INDEX "idx_offers_status_expiry"
ON "offers" ("status", "expires_at");

CREATE TABLE IF NOT EXISTS "offer_approvals" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Offer being approved.
	"offer_id" BIGINT NOT NULL,
	-- Employee whose sign-off is needed.
	"approver_user_id" BIGINT NOT NULL,
	-- Position in the chain. Approvals are sequential, so a step is only actionable once the one before it is approved.
	"step_order" SMALLINT NOT NULL,
	-- pending | approved | rejected | skipped. Skipped covers a delegated or auto-approved step that still has to appear in the record.
	"decision" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- When they responded. Null while pending, which is what the reminder job queries.
	"decided_at" TIMESTAMP,
	-- Conditions attached to the approval, e.g. "approved at this number only".
	"comment" TEXT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "offer_approvals" IS 'The approval chain as ordered rows. Modelling it as a list rather than as approver columns on the offer is what lets a chain be three people for one role and six for another, and leaves an audit trail of who signed off on what number.';
COMMENT ON COLUMN "offer_approvals"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "offer_approvals"."offer_id" IS 'Offer being approved.';
COMMENT ON COLUMN "offer_approvals"."approver_user_id" IS 'Employee whose sign-off is needed.';
COMMENT ON COLUMN "offer_approvals"."step_order" IS 'Position in the chain. Approvals are sequential, so a step is only actionable once the one before it is approved.';
COMMENT ON COLUMN "offer_approvals"."decision" IS 'pending | approved | rejected | skipped. Skipped covers a delegated or auto-approved step that still has to appear in the record.';
COMMENT ON COLUMN "offer_approvals"."decided_at" IS 'When they responded. Null while pending, which is what the reminder job queries.';
COMMENT ON COLUMN "offer_approvals"."comment" IS 'Conditions attached to the approval, e.g. "approved at this number only".';

CREATE UNIQUE INDEX "uq_offer_approval_step"
ON "offer_approvals" ("offer_id", "step_order");
CREATE INDEX "idx_offer_approvals_inbox"
ON "offer_approvals" ("approver_user_id", "decision");

CREATE TABLE IF NOT EXISTS "talent_pool_entries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Person being kept warm.
	"candidate_id" BIGINT NOT NULL,
	-- Application they nearly won. Null for sourced candidates added directly to the pool.
	"source_application_id" BIGINT,
	-- silver_medalist | future_fit | sourced | boomerang. The pools a recruiter searches first when a similar role opens.
	"pool_name" VARCHAR(80) NOT NULL DEFAULT 'silver_medalist',
	-- Who added them.
	"added_by_user_id" BIGINT,
	-- Why they are worth revisiting, written while it is fresh. Six months later nobody remembers what was good about candidate 4,812.
	"reason" TEXT,
	-- Earliest sensible date to reach out again, typically after they have had time in their current role.
	"revisit_after" DATE,
	-- When they left the pool, whether by being hired or by asking not to be contacted.
	"removed_at" TIMESTAMP,
	-- When they entered the pool.
	"added_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "talent_pool_entries" IS 'Silver medallists and other near misses. A rejected application is a dead end by design, so a strong candidate who lost to someone stronger needs an explicit record to be findable — otherwise the most valuable pipeline a company owns disappears into a rejection filter.';
COMMENT ON COLUMN "talent_pool_entries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "talent_pool_entries"."candidate_id" IS 'Person being kept warm.';
COMMENT ON COLUMN "talent_pool_entries"."source_application_id" IS 'Application they nearly won. Null for sourced candidates added directly to the pool.';
COMMENT ON COLUMN "talent_pool_entries"."pool_name" IS 'silver_medalist | future_fit | sourced | boomerang. The pools a recruiter searches first when a similar role opens.';
COMMENT ON COLUMN "talent_pool_entries"."added_by_user_id" IS 'Who added them.';
COMMENT ON COLUMN "talent_pool_entries"."reason" IS 'Why they are worth revisiting, written while it is fresh. Six months later nobody remembers what was good about candidate 4,812.';
COMMENT ON COLUMN "talent_pool_entries"."revisit_after" IS 'Earliest sensible date to reach out again, typically after they have had time in their current role.';
COMMENT ON COLUMN "talent_pool_entries"."removed_at" IS 'When they left the pool, whether by being hired or by asking not to be contacted.';
COMMENT ON COLUMN "talent_pool_entries"."added_at" IS 'When they entered the pool.';

CREATE INDEX "idx_talent_pool_revisit"
ON "talent_pool_entries" ("pool_name", "revisit_after");
CREATE INDEX "idx_talent_pool_candidate"
ON "talent_pool_entries" ("candidate_id");

